-- Micaforge: the Postgres schema.
--
-- Authoritative source: docs/CONTRACT.md §2. This file exists to make Postgres
-- match the row structs in `micaforge_store::models`, not the other way round.
-- If a column here is not selected by a query there, it is either an index the
-- queries need or a timestamp an operator needs; nothing else was added.
--
-- Conventions, stated once rather than repeated on forty tables:
--
--   * Primary keys are UUIDv7, generated by the application (`micaforge_core::new_id`).
--     They sort by creation time, so `ORDER BY id` is a chronological order with
--     no second index, and an id exists before the insert so a caller never needs
--     RETURNING to learn what it just made. There is no `gen_random_uuid()`
--     default: a row without an application-supplied id would be a bug that this
--     schema quietly repaired.
--   * Enums are TEXT + CHECK, per the contract. The vocabularies below are the
--     same strings the Rust side writes; `micaforge_core::Error` maps a check
--     violation to a 400, so a bad value is reported as the caller's fault.
--   * `site_id` on a child table is `sites.id`, the UUID. The small integer that
--     ClickHouse keys on is `sites.site_id`, and the two are never
--     interchangeable. Confusing them is the single most likely way to write a
--     query that returns another tenant's data.
--   * Deletes cascade downwards and are restricted upwards. Deleting a site takes
--     its goals, funnels, alerts and share links with it, because none of them
--     mean anything without it. Deleting a user does NOT take their organisation:
--     `organizations.owner_id` is RESTRICT, so the transfer has to be deliberate.

-- Case-insensitive email comparison, so `Ada@Example.com` and `ada@example.com`
-- cannot both hold accounts. citext has been a trusted extension since
-- PostgreSQL 13, so the database owner can create it without superuser rights.
-- The application lowercases addresses on the way in as well; this is the
-- constraint that makes it true rather than merely habitual.
CREATE EXTENSION IF NOT EXISTS citext;

-- ---------------------------------------------------------------------------
-- Identity
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS users (
    id                  uuid PRIMARY KEY,
    email               citext NOT NULL UNIQUE,
    -- Argon2id, in PHC string form. Never empty: an account with no password is
    -- an account anybody can sign in to.
    password_hash       text NOT NULL,
    name                text NOT NULL,
    avatar_url          text,
    email_verified_at   timestamptz,
    -- XChaCha20-Poly1305, keyed off MICAFORGE_SECRET_KEY_BASE. Bytes rather than
    -- text because it is a sealed blob and never anything a person reads.
    totp_secret_sealed  bytea,
    created_at          timestamptz NOT NULL DEFAULT now()
);

-- `users::list` pages the admin screen by this order.
CREATE INDEX IF NOT EXISTS users_created_at_idx ON users (created_at DESC, id DESC);

CREATE TABLE IF NOT EXISTS organizations (
    id          uuid PRIMARY KEY,
    name        text NOT NULL,
    slug        text NOT NULL UNIQUE,
    -- RESTRICT, not CASCADE. An organisation holds sites, keys and history;
    -- deleting the person who happens to own it must never take those with it.
    -- `routes::admin` refuses the delete first and explains; this is the
    -- guarantee underneath that check.
    owner_id    uuid NOT NULL REFERENCES users (id) ON DELETE RESTRICT,
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS organizations_owner_idx ON organizations (owner_id);
CREATE INDEX IF NOT EXISTS organizations_created_at_idx ON organizations (created_at DESC, id DESC);

CREATE TABLE IF NOT EXISTS org_members (
    org_id      uuid NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
    user_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role        text NOT NULL CHECK (role IN ('owner', 'admin', 'member', 'viewer')),
    created_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (org_id, user_id)
);

-- `orgs::list_for_user` and `sites::list_sites_for_user` both start here.
CREATE INDEX IF NOT EXISTS org_members_user_idx ON org_members (user_id);

CREATE TABLE IF NOT EXISTS teams (
    id          uuid PRIMARY KEY,
    org_id      uuid NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
    name        text NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS teams_org_idx ON teams (org_id);

CREATE TABLE IF NOT EXISTS team_members (
    team_id  uuid NOT NULL REFERENCES teams (id) ON DELETE CASCADE,
    user_id  uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    PRIMARY KEY (team_id, user_id)
);

CREATE INDEX IF NOT EXISTS team_members_user_idx ON team_members (user_id);

-- The dashboard's session cookie. What is stored is a SHA-256 digest of the
-- token, so a dump of this table yields nothing anybody can sign in with.
CREATE TABLE IF NOT EXISTS sessions_auth (
    id          uuid PRIMARY KEY,
    user_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash  text NOT NULL UNIQUE,
    user_agent  text,
    -- Salted, never the address itself. `docs/CONTRACT.md` §7.1 is about event
    -- rows, but there is no reason for an auth row to be the exception.
    ip_hash     text,
    expires_at  timestamptz NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS sessions_auth_user_idx ON sessions_auth (user_id);
-- `auth::purge_expired` sweeps on this.
CREATE INDEX IF NOT EXISTS sessions_auth_expires_idx ON sessions_auth (expires_at);

-- ---------------------------------------------------------------------------
-- Sites
-- ---------------------------------------------------------------------------

-- The numeric id every ClickHouse table keys on, as UInt16.
--
-- A dedicated sequence rather than `serial` so the ceiling is explicit: the
-- column is UInt16 in the event store, so an install is capped at 65,535 sites
-- and the sequence says so. Running out raises an error at the insert, which is
-- the honest failure; wrapping round would hand a new site another site's
-- history.
CREATE SEQUENCE IF NOT EXISTS sites_site_id_seq AS integer MINVALUE 1 MAXVALUE 65535 START 1;

CREATE TABLE IF NOT EXISTS sites (
    id              uuid PRIMARY KEY,
    -- `integer`, not `smallint`, even though the value never exceeds 65,535.
    -- Postgres has no unsigned types: `smallint` tops out at 32,767, which would
    -- forbid half the legal range, and `micaforge_store::models::sites::Site`
    -- decodes this column as `i32`, which a runtime-checked sqlx read will refuse
    -- to take from an INT2. The CHECK is what actually enforces the contract.
    site_id         integer NOT NULL UNIQUE DEFAULT nextval('sites_site_id_seq')
                        CHECK (site_id BETWEEN 1 AND 65535),
    org_id          uuid NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
    -- One property per hostname across the install. Two sites collecting the
    -- same domain would split every number in half with no way to tell which
    -- half was which, and the ingest path resolves a hit by hostname.
    domain          text NOT NULL UNIQUE,
    name            text NOT NULL,
    timezone        text NOT NULL DEFAULT 'UTC',
    "public"        boolean NOT NULL DEFAULT false,
    salt_rotated_at timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now(),
    -- Tracking options, and the sealed per-site ingest key. jsonb because the
    -- shape is the settings screen's business and changes without a migration.
    settings        jsonb NOT NULL DEFAULT '{}'::jsonb
);

ALTER SEQUENCE sites_site_id_seq OWNED BY sites.site_id;

CREATE INDEX IF NOT EXISTS sites_org_idx ON sites (org_id);

-- Per-site role, overriding the organisation role in BOTH directions: it can
-- narrow an org admin to a viewer on one sensitive property, and widen an org
-- viewer to a member on the one site they actually run.
CREATE TABLE IF NOT EXISTS site_access (
    site_id  uuid NOT NULL REFERENCES sites (id) ON DELETE CASCADE,
    user_id  uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role     text NOT NULL CHECK (role IN ('owner', 'admin', 'member', 'viewer')),
    PRIMARY KEY (site_id, user_id)
);

CREATE INDEX IF NOT EXISTS site_access_user_idx ON site_access (user_id);

CREATE TABLE IF NOT EXISTS share_links (
    id             uuid PRIMARY KEY,
    site_id        uuid NOT NULL REFERENCES sites (id) ON DELETE CASCADE,
    slug           text NOT NULL UNIQUE,
    -- Argon2id when the link is protected, NULL when it is open. NULL is not a
    -- weaker password; it means the link itself is the credential.
    password_hash  text,
    expires_at     timestamptz,
    scopes         jsonb NOT NULL DEFAULT '[]'::jsonb,
    created_at     timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS share_links_site_idx ON share_links (site_id);

-- ---------------------------------------------------------------------------
-- Credentials
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS api_keys (
    id            uuid PRIMARY KEY,
    org_id        uuid NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
    -- NULL means the key reaches every site in the organisation. A key pinned to
    -- a site dies with it, because a credential scoped to something that no
    -- longer exists is a credential with no meaning.
    site_id       uuid REFERENCES sites (id) ON DELETE CASCADE,
    name          text NOT NULL,
    -- The first 16 characters of the token, in the clear and indexed. Not a
    -- secret: it is the lookup key, and it is what the settings screen shows so
    -- one key can be told from its siblings.
    prefix        text NOT NULL,
    -- SHA-256 of the whole token. This is what authenticates.
    hash          text NOT NULL,
    scopes        jsonb NOT NULL DEFAULT '[]'::jsonb,
    last_used_at  timestamptz,
    expires_at    timestamptz,
    created_at    timestamptz NOT NULL DEFAULT now()
);

-- `keys::find_by_prefix` is on the authentication path of every API-key request.
CREATE INDEX IF NOT EXISTS api_keys_prefix_idx ON api_keys (prefix);
CREATE INDEX IF NOT EXISTS api_keys_org_idx ON api_keys (org_id);

-- ---------------------------------------------------------------------------
-- What a site measures
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS goals (
    id           uuid PRIMARY KEY,
    site_id      uuid NOT NULL REFERENCES sites (id) ON DELETE CASCADE,
    name         text NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('path', 'event', 'outbound', 'file', 'revenue')),
    -- The same filter shape the API takes (docs/CONTRACT.md §3.2), which is what
    -- lets a goal and an ad-hoc filter compile to the same SQL.
    conditions   jsonb NOT NULL DEFAULT '{}'::jsonb,
    value_cents  bigint NOT NULL DEFAULT 0,
    created_at   timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS goals_site_idx ON goals (site_id);

CREATE TABLE IF NOT EXISTS funnels (
    id            uuid PRIMARY KEY,
    site_id       uuid NOT NULL REFERENCES sites (id) ON DELETE CASCADE,
    name          text NOT NULL,
    steps         jsonb NOT NULL DEFAULT '[]'::jsonb,
    -- How long a visitor has to complete the funnel. Zero would make every
    -- funnel report nothing, which looks like no conversions rather than a
    -- misconfiguration.
    window_hours  integer NOT NULL DEFAULT 24 CHECK (window_hours > 0),
    created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS funnels_site_idx ON funnels (site_id);

CREATE TABLE IF NOT EXISTS segments (
    id          uuid PRIMARY KEY,
    site_id     uuid NOT NULL REFERENCES sites (id) ON DELETE CASCADE,
    name        text NOT NULL,
    filters     jsonb NOT NULL DEFAULT '{}'::jsonb,
    shared      boolean NOT NULL DEFAULT false,
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS segments_site_idx ON segments (site_id);

CREATE TABLE IF NOT EXISTS dashboards (
    id          uuid PRIMARY KEY,
    site_id     uuid NOT NULL REFERENCES sites (id) ON DELETE CASCADE,
    name        text NOT NULL,
    layout      jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS dashboards_site_idx ON dashboards (site_id);

-- ---------------------------------------------------------------------------
-- Experimentation
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS feature_flags (
    id           uuid PRIMARY KEY,
    site_id      uuid NOT NULL REFERENCES sites (id) ON DELETE CASCADE,
    key          text NOT NULL,
    enabled      boolean NOT NULL DEFAULT false,
    rollout_pct  integer NOT NULL DEFAULT 0 CHECK (rollout_pct BETWEEN 0 AND 100),
    variants     jsonb NOT NULL DEFAULT '[]'::jsonb,
    conditions   jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at   timestamptz NOT NULL DEFAULT now(),
    -- `flags::get_flag_by_key` looks a flag up by this pair on every evaluation,
    -- and two flags with one key on one site would make which of them applies a
    -- coin toss.
    UNIQUE (site_id, key)
);

CREATE TABLE IF NOT EXISTS experiments (
    id          uuid PRIMARY KEY,
    site_id     uuid NOT NULL REFERENCES sites (id) ON DELETE CASCADE,
    key         text NOT NULL,
    hypothesis  text NOT NULL DEFAULT '',
    variants    jsonb NOT NULL DEFAULT '[]'::jsonb,
    -- SET NULL, not CASCADE. Deleting the goal an experiment measured should
    -- leave the experiment and its recorded exposures readable; throwing the
    -- whole experiment away would destroy the record of what was tried.
    goal_id     uuid REFERENCES goals (id) ON DELETE SET NULL,
    status      text NOT NULL DEFAULT 'draft'
                    CHECK (status IN ('draft', 'running', 'paused', 'finished')),
    started_at  timestamptz,
    ended_at    timestamptz,
    created_at  timestamptz NOT NULL DEFAULT now(),
    UNIQUE (site_id, key)
);

CREATE INDEX IF NOT EXISTS experiments_site_idx ON experiments (site_id);

-- ---------------------------------------------------------------------------
-- Notification
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS alerts (
    id             uuid PRIMARY KEY,
    site_id        uuid NOT NULL REFERENCES sites (id) ON DELETE CASCADE,
    kind           text NOT NULL CHECK (
                       kind IN ('spike', 'drop', 'goal', 'error', 'agent_surge', 'citation_gap')
                   ),
    config         jsonb NOT NULL DEFAULT '{}'::jsonb,
    channels       jsonb NOT NULL DEFAULT '[]'::jsonb,
    -- The cooldown is read from here by `alerts::try_fire_alert`, which claims
    -- the alert in one statement so two workers cannot both send.
    last_fired_at  timestamptz,
    created_at     timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS alerts_site_idx ON alerts (site_id);

CREATE TABLE IF NOT EXISTS reports (
    id           uuid PRIMARY KEY,
    site_id      uuid NOT NULL REFERENCES sites (id) ON DELETE CASCADE,
    cadence      text NOT NULL CHECK (cadence IN ('daily', 'weekly', 'monthly')),
    recipients   jsonb NOT NULL DEFAULT '[]'::jsonb,
    channels     jsonb NOT NULL DEFAULT '[]'::jsonb,
    next_run_at  timestamptz,
    created_at   timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS reports_site_idx ON reports (site_id);
-- `alerts::due_reports` sweeps every fifteen minutes; a partial index keeps that
-- sweep off every report that has no next run scheduled.
CREATE INDEX IF NOT EXISTS reports_due_idx ON reports (next_run_at) WHERE next_run_at IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Imports
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS imports (
    id          uuid PRIMARY KEY,
    site_id     uuid NOT NULL REFERENCES sites (id) ON DELETE CASCADE,
    source      text NOT NULL CHECK (source IN ('ga4', 'plausible', 'umami')),
    status      text NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending', 'running', 'done', 'failed')),
    progress    integer NOT NULL DEFAULT 0 CHECK (progress BETWEEN 0 AND 100),
    error       text,
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS imports_site_idx ON imports (site_id, created_at DESC);

-- ---------------------------------------------------------------------------
-- The agent catalog, and each site's stated policy
-- ---------------------------------------------------------------------------

-- Named non-human clients. Seeded from the compiled-in catalog by
-- 0002_seed_agent_catalog.sql and kept current by the `refresh_agent_ranges`
-- job, which is the only thing that writes `ip_ranges`.
CREATE TABLE IF NOT EXISTS agent_catalog (
    slug             text PRIMARY KEY,
    display_name     text NOT NULL,
    operator         text NOT NULL,
    purpose          text NOT NULL DEFAULT 'unknown'
                         CHECK (purpose IN ('training', 'rag', 'search', 'preview', 'eval', 'unknown')),
    -- Substrings matched against the user-agent header, longest first.
    ua_patterns      jsonb NOT NULL DEFAULT '[]'::jsonb,
    -- CIDR strings from the operator's published range document. This is what
    -- makes `agent_events.verified` mean something rather than repeat a claim.
    ip_ranges        jsonb NOT NULL DEFAULT '[]'::jsonb,
    rdns_suffixes    jsonb NOT NULL DEFAULT '[]'::jsonb,
    docs_url         text,
    -- What the operator SAYS. A violation report is the difference between this
    -- and what was observed, so it is a claim on the record, never a fact.
    respects_robots  boolean NOT NULL DEFAULT true,
    updated_at       timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS agent_catalog_operator_idx ON agent_catalog (operator);

-- A site's own robots.txt and llms.txt, kept verbatim so an audit can be
-- repeated against the exact bytes that were in force.
CREATE TABLE IF NOT EXISTS site_policy (
    site_id     uuid PRIMARY KEY REFERENCES sites (id) ON DELETE CASCADE,
    robots_txt  text,
    llms_txt    text,
    fetched_at  timestamptz,
    parsed      jsonb NOT NULL DEFAULT '{}'::jsonb
);

-- `catalog::stale_policies` orders by this, NULLS FIRST, to pick the next crawl.
CREATE INDEX IF NOT EXISTS site_policy_fetched_idx ON site_policy (fetched_at NULLS FIRST);

-- ---------------------------------------------------------------------------
-- The job queue
-- ---------------------------------------------------------------------------

-- Postgres is the queue. `SELECT ... FOR UPDATE SKIP LOCKED` is what makes
-- several replicas of one binary safe against each other, and it is why there is
-- no fourth service in the compose file.
CREATE TABLE IF NOT EXISTS jobs (
    id         uuid PRIMARY KEY,
    kind       text NOT NULL,
    payload    jsonb NOT NULL DEFAULT '{}'::jsonb,
    run_at     timestamptz NOT NULL DEFAULT now(),
    attempts   integer NOT NULL DEFAULT 0,
    -- Which worker lane holds this row, and since when. The janitor reclaims a
    -- row whose lane died by looking at `locked_at`.
    locked_by  text,
    locked_at  timestamptz,
    status     text NOT NULL DEFAULT 'pending'
                   CHECK (status IN ('pending', 'running', 'done', 'failed')),
    created_at timestamptz NOT NULL DEFAULT now()
);

-- The claim query: status, then run_at, then kind. A partial index on the
-- pending rows keeps the queue's working set small however much finished history
-- accumulates behind it.
CREATE INDEX IF NOT EXISTS jobs_claim_idx ON jobs (run_at, id) WHERE status = 'pending';
-- The janitor's sweep for lanes that died mid-job.
CREATE INDEX IF NOT EXISTS jobs_running_idx ON jobs (locked_at) WHERE status = 'running';
-- The admin queue view, and `jobs::purge_finished`.
CREATE INDEX IF NOT EXISTS jobs_status_idx ON jobs (status, run_at DESC);
